import { expect, test, type APIRequestContext } from "@playwright/test";
import fs from "node:fs";

/**
 * Manuscript export. There is no export screen yet, so the test drives a real
 * browser download of the endpoint the UI will use: an anchor with a `download`
 * attribute, which exercises Content-Disposition, the generated bytes, and the
 * filename the author ends up with.
 */
test.describe.configure({ mode: "serial" });

const PROSE = "The harbour was quiet and the beacon still turned.";

/** Create a novel with two written chapters through the public API. */
async function seedManuscript(request: APIRequestContext, title: string) {
  const novel = await request.post("/api/novels", { data: { title } });
  expect(novel.ok(), "novel creation should succeed").toBeTruthy();
  const { id: novelId } = (await novel.json()) as { id: number };

  for (const [chapterTitle, body] of [
    ["The Beacon", PROSE],
    ["The Crossing", "By morning the ferry had gone."],
  ]) {
    const chapter = await request.post(`/api/novels/${novelId}/chapters`, { data: { title: chapterTitle } });
    expect(chapter.ok(), "chapter creation should succeed").toBeTruthy();
    const { id: chapterId } = (await chapter.json()) as { id: number };
    const saved = await request.put(`/api/chapters/${chapterId}?source=manual`, { data: { body } });
    expect(saved.ok(), "chapter body save should succeed").toBeTruthy();
  }

  return { novelId };
}

/** Click a throwaway download link and return the bytes the browser received. */
async function download(page: import("@playwright/test").Page, href: string) {
  const started = page.waitForEvent("download");
  await page.evaluate((url) => {
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = "";
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
  }, href);
  const file = await started;
  expect(await file.failure(), "the download should not fail").toBeNull();
  const path = await file.path();
  expect(path, "the browser should keep the file locally").toBeTruthy();
  return { filename: file.suggestedFilename(), bytes: fs.readFileSync(path!) };
}

test("export: the manuscript downloads as DOCX, plain text, Markdown and PDF", async ({ page, request }) => {
  const { novelId } = await seedManuscript(request, "Tidewater Ledger");
  await page.goto("/");

  // DOCX: a real Office archive, named from the novel title.
  const docx = await download(page, `/api/novels/${novelId}/export?format=docx`);
  expect(docx.filename).toBe("tidewater-ledger.docx");
  expect(docx.bytes.subarray(0, 2).toString("latin1"), "a DOCX is a ZIP archive").toBe("PK");
  expect(docx.bytes.includes(Buffer.from("word/document.xml", "latin1")), "the archive holds a Word document").toBeTruthy();
  expect(docx.bytes.byteLength).toBeGreaterThan(1024);

  // Plain text: the same manuscript, readable end to end.
  const txt = await download(page, `/api/novels/${novelId}/export?format=txt`);
  expect(txt.filename).toBe("tidewater-ledger.txt");
  const text = txt.bytes.toString("utf8");
  expect(text).toContain("Tidewater Ledger");
  expect(text).toContain("The Beacon");
  expect(text).toContain("The Crossing");
  expect(text).toContain(PROSE);
  expect(text).toContain("By morning the ferry had gone.");
  // Chapters keep manuscript order, not creation order.
  expect(text.indexOf("The Beacon")).toBeLessThan(text.indexOf("The Crossing"));

  // Through the control the client actually offers, defaulting to Markdown.
  await page.goto("/novels");
  const card = page.locator("div.rounded-xl").filter({ hasText: "Tidewater Ledger" });
  const picker = card.getByLabel("Export format for Tidewater Ledger");
  await expect(picker).toHaveValue("markdown");

  const startedMarkdown = page.waitForEvent("download");
  await card.getByRole("button", { name: "Export", exact: true }).click();
  const md = await startedMarkdown;
  expect(md.suggestedFilename()).toBe("tidewater-ledger.md");
  const markdown = fs.readFileSync((await md.path())!, "utf8");
  expect(markdown).toContain("# Tidewater Ledger");
  expect(markdown).toContain("## The Beacon");
  expect(markdown).toContain("## The Crossing");
  expect(markdown).toContain(PROSE);

  // The same control reaches the other formats: switching to DOCX changes the file.
  await picker.selectOption("docx");
  const startedDocx = page.waitForEvent("download");
  await card.getByRole("button", { name: "Export", exact: true }).click();
  const docxAgain = await startedDocx;
  expect(docxAgain.suggestedFilename()).toBe("tidewater-ledger.docx");
  expect(
    fs
      .readFileSync((await docxAgain.path())!)
      .subarray(0, 2)
      .toString("latin1"),
  ).toBe("PK");

  // PDF: a complete document, not a truncated or empty stream.
  await picker.selectOption("pdf");
  const startedPdf = page.waitForEvent("download");
  await card.getByRole("button", { name: "Export", exact: true }).click();
  const pdf = await startedPdf;
  expect(await pdf.failure()).toBeNull();
  expect(pdf.suggestedFilename()).toBe("tidewater-ledger.pdf");
  const pdfBytes = fs.readFileSync((await pdf.path())!);
  expect(pdfBytes.subarray(0, 5).toString("latin1"), "a PDF starts with %PDF-").toBe("%PDF-");
  expect(pdfBytes.subarray(-1024).toString("latin1"), "pdfkit ends the file with %%EOF").toContain("%%EOF");
  expect(pdfBytes.byteLength).toBeGreaterThan(1024);
});
